import{_ as n,a0 as a,w as s,s as d,ao as p,I as i,x as e,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse(`{"title":"Torvalds: 写linux内核的人更加容易找工作 | LCTT x X-CMD","titleTemplate":false,"description":"Torvalds: 写linux内核的人更加容易找工作 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Torvalds: 写linux内核的人更加容易找工作 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Torvalds: 写linux内核的人更加容易找工作 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150225 Torvalds--'People who start writing kernel code get hired really quickly'","title":"Torvalds: 写linux内核的人更加容易找工作","tag":"201504","desc":""},"relativePath":"201504/20150225 Torvalds--'People who start writing kernel code get hired really quickly'.md","filePath":"[post].md"}`),u={name:"201504/20150225 Torvalds--'People who start writing kernel code get hired really quickly'.md"};function m(T,t,x,g,w,f){const l=a("Link");return s(),d("div",null,[t[13]||(t[13]=p('<h1 id="torvalds-写linux内核的人更加容易找工作" tabindex="-1">Torvalds: 写linux内核的人更加容易找工作 <a class="header-anchor" href="#torvalds-写linux内核的人更加容易找工作" aria-label="Permalink to “Torvalds: 写linux内核的人更加容易找工作”">​</a></h1><p>相比起以往，linux内核开发这么专业的事情，在最近发布的《谁在编写 Linux》报告中，其无偿贡献者降到了历史最低水平。</p><p>这个报道由linux基金会撰写，上年有11.8%的内核开发是由无偿贡献者完成，相比2012年的14.6%下滑了19%。基金会说贡献者有逐年下降的趋势。</p><p><img src="http://images.techhive.com/images/article/2015/02/screen-shot-2015-02-17-at-5.25.43-pm-100568680-medium.idge.png" alt=""></p><p>即使是这样，在最新的《谁在编写 Linux》报告里，无偿贡献者还是最大的单一贡献来源，共做了11968 处修改，占整体的12.4%。然而，linux基金会说，企业贡献者共同占比越来越多，超过80%的内核贡献是由有偿的专业开发者完成的。</p><p>根据 linus Torvalds 说，这个有偿开发者趋势不会对内核开发的本身有太多改变。</p><p>他向《Network World》说，“我认为不会改变太多的一个原因是，其实并不是‘无偿贡献者离开了’，而是‘编写内核的人很快就被雇走了’。”</p><p>Torvalds讲到，linux开发的改变有很多其他原因，很自然的，新的贡献者会经常冒出来；有很多原来的开发者，有的有着10年的经验，被很多对linux感兴趣的公司抢去了。</p><p>他说：“开始我们是自愿者，但我们后来也很高兴被请去开发linux。”</p><p>Torvalds 开始抽离了他的开发角色，根据报道在3.10的内核版本里面他个人发布了329个补丁，占04%。逐渐地，各个子系统的维护人员自己开始做代码检查与合并。</p><hr>',11)),i("p",null,[t[1]||(t[1]=e("via: ",-1)),r(l,{href:"http://www.infoworld.com/article/2885339/application-development/torvalds-people-who-start-writing-kernel-code-get-hired-really-quickly.html"},{default:o(()=>[...t[0]||(t[0]=[e("http://www.infoworld.com/article/2885339/application-development/torvalds-people-who-start-writing-kernel-code-get-hired-really-quickly.html",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=e("作者：",-1)),r(l,{href:"http://www.infoworld.com/author/Jon-Gold/"},{default:o(()=>[...t[2]||(t[2]=[e("Jon Gold",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),r(l,{href:"https://github.com/haimingfg"},{default:o(()=>[...t[3]||(t[3]=[e("haimingfg",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),r(l,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=e("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),r(l,{href:"http://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const _=n(u,[["render",m]]);export{k as __pageData,_ as default};
